input.newString:
function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = getListingById(id);
  if (!listing) {
    return undefined;
  }
  const transitionRules = new Map<string, string[]>();
  transitionRules.set('active', ['fulfilled', 'deleted']);
  transitionRules.set('fulfilled', ['deleted']);
  const allowedTo = transitionRules.get(listing.status);
  if (!allowedTo || !allowedTo.includes(status)) {
    throw new Error(
      `Cannot transition listing #${id} from status '${listing.status}' to '${status}'.`,
    );
  }
  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

