describe('status transition guard', () => {
  function seedForTransition(id: number, status: 'active' | 'fulfilled' | 'deleted' | 'expired'): void {
    const db = getDb();
    db
      .insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Test Card',
        cardNameNormalized: 'test card',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status,
        expiresAt: Date.now() + 30 * 24 * 3600 * 1000,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      })
      .run();
  }

  it('allows active to fulfilled', () => {
    seedForTransition(1, 'active');
    const result = fulfillListing(1);
    expect(result).toBeDefined();
    expect(result?.status).toBe('fulfilled');
  });

  it('allows active to deleted', () => {
    seedForTransition(1, 'active');
    const result = softDeleteListing(1);
    expect(result).toBeDefined();
    expect(result?.status).toBe('deleted');
  });

  it('allows fulfilled to deleted (cleanup)', () => {
    seedForTransition(1, 'fulfilled');
    const result = softDeleteListing(1);
    expect(result).toBeDefined();
    expect(result?.status).toBe('deleted');
  });

  it('forbids re-fulfilling an already-fulfilled listing', () => {
    seedForTransition(1, 'fulfilled');
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'fulfilled' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('fulfilled');
  });

  it('forbids re-deleting an already-deleted listing', () => {
    seedForTransition(1, 'deleted');
    expect(() => softDeleteListing(1)).toThrow(/cannot transition from 'deleted' to 'deleted'/);
    const result = getListingById(1);
    expect(result?.status).toBe('deleted');
  });

  it('forbids fulfilling a deleted listing', () => {
    seedForTransition(1, 'deleted');
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'deleted' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('deleted');
  });

  it('forbids fulfilling an expired listing', () => {
    seedForTransition(1, 'expired');
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'expired' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('expired');
  });

  it('forbids deleting an expired listing', () => {
    seedForTransition(1, 'expired');
    expect(() => softDeleteListing(1)).toThrow(/cannot transition from 'expired' to 'deleted'/);
    const result = getListingById(1);
    expect(result?.status).toBe('expired');
  });

  it('forbids transitioning active to fulfilled then back to active', () => {
    seedForTransition(1, 'active');
    fulfillListing(1);
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'fulfilled' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('fulfilled');
  });

  it('forbids transitioning active to deleted then back to active', () => {
    seedForTransition(1, 'active');
    softDeleteListing(1);
    expect(() => softDeleteListing(1)).toThrow(/cannot transition from 'deleted' to 'deleted'/);
    const result = getListingById(1);
    expect(result?.status).toBe('deleted');
  });

  it('forbids transitioning fulfilled to deleted then back to fulfilled', () => {
    seedForTransition(1, 'fulfilled');
    softDeleteListing(1);
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'deleted' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('deleted');
  });

  it('forbids transitioning active to fulfilled then to deleted then to fulfilled', () => {
    seedForTransition(1, 'active');
    fulfillListing(1);
    softDeleteListing(1);
    expect(() => fulfillListing(1)).toThrow(/cannot transition from 'deleted' to 'fulfilled'/);
    const result = getListingById(1);
    expect(result?.status).toBe('deleted');
  });
});

