        quantity: 1,
        notes: null,
        status,
        expiresAt: Date.now() + 30 * 24 * 3600 * 1000,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      })
      .run();
  }

  it('allows active to fulfilled', () => {
    seedForTransition(1, 'active');
